import{_ as t,o as r,c as a,a3 as d}from"./chunks/framework._FWOmmqu.js";const u=JSON.parse('{"title":"Product Roadmap","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Product Roadmap | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/getting-started/product-roadmap"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Product Roadmap | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/getting-started/product-roadmap"}]]},"headers":[],"relativePath":"getting-started/product-roadmap.md","filePath":"getting-started/product-roadmap.md","lastUpdated":1789669215000}'),o={name:"getting-started/product-roadmap.md"};function s(i,e,n,p,l,c){return r(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="product-roadmap" tabindex="-1">Product Roadmap <a class="header-anchor" href="#product-roadmap" aria-label="Permalink to &quot;Product Roadmap&quot;">​</a></h1><p>Canonical delivery status for EloSync modules and platform capabilities. Keep this page aligned with <a href="/architecture/module-dependencies">module dependencies</a>, <a href="/changelog/">changelog</a>, user-guide overviews, and the marketing site roadmap.</p><p><strong>Legend:</strong> Shipped = available in product; Deferred = documented later work; Demand-driven = only when beta tenants ask.</p><hr><h2 id="phase-1-—-crm-foundation-shipped" tabindex="-1">Phase 1 — CRM Foundation (shipped) <a class="header-anchor" href="#phase-1-—-crm-foundation-shipped" aria-label="Permalink to &quot;Phase 1 — CRM Foundation (shipped)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Status</th></tr></thead><tbody><tr><td><a href="/user-guide/leads-overview">Leads</a>, <a href="/user-guide/tasks-overview">Tasks</a>, <a href="/user-guide/todos-overview">ToDos</a></td><td>Shipped (default-included; Leads <strong>1.5.0</strong> convert polish; Tasks <strong>1.5.0</strong> milestone link + dependencies)</td></tr><tr><td><a href="/user-guide/contacts-overview">Contacts</a>, <a href="/user-guide/companies-overview">Companies</a></td><td>Shipped</td></tr><tr><td><a href="/user-guide/calendar-overview">Calendar</a>, <a href="/user-guide/meetings-overview">Meetings</a></td><td>Shipped (Meetings requires Calendar; Calendar <strong>1.1.0</strong> Task/Lead overlays)</td></tr><tr><td><a href="/user-guide/activities-overview">Activities</a>, <a href="/user-guide/communication-templates">Communication Templates</a></td><td>Shipped</td></tr><tr><td>Module Marketplace</td><td>Shipped</td></tr><tr><td>Meta Lead Ads / inbound webhooks</td><td>Shipped</td></tr><tr><td><a href="/user-guide/whatsapp-cloud-overview">WhatsApp Cloud</a></td><td>Shipped (billable; media + Automation triggers shipped; interactive buttons/lists deferred)</td></tr></tbody></table><h3 id="planned-deferred-after-phase-1-mvp" tabindex="-1">Planned / deferred after Phase 1 MVP <a class="header-anchor" href="#planned-deferred-after-phase-1-mvp" aria-label="Permalink to &quot;Planned / deferred after Phase 1 MVP&quot;">​</a></h3><ul><li>Calendar: team calendars / shared ACL, Google/Outlook sync</li><li>Meetings: invitee Calendar ACL for projected events</li><li>Leads: real-time board sync</li><li>WhatsApp: interactive buttons/lists, alternate BSPs, AI WhatsApp features</li></ul><p><strong>Shipped depth (CRM):</strong> Calendar Task/Lead overlays (<strong>calendar 1.1.0</strong>); Lead convert polish — Companies link + <code>LeadConverted</code> / Automation <code>lead.converted</code> (<strong>leads 1.5.0</strong>).</p><hr><h2 id="phase-2-—-sales-expansion-shipped" tabindex="-1">Phase 2 — Sales Expansion (shipped) <a class="header-anchor" href="#phase-2-—-sales-expansion-shipped" aria-label="Permalink to &quot;Phase 2 — Sales Expansion (shipped)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Status</th></tr></thead><tbody><tr><td><a href="/user-guide/opportunities-overview">Opportunities</a> (pipeline + Kanban)</td><td>Shipped</td></tr><tr><td><a href="/user-guide/quotations-overview">Quotations</a></td><td>Shipped (requires Opportunities; customer e-signature accept links <strong>1.9.0</strong>)</td></tr><tr><td><a href="/user-guide/contracts-overview">Contracts</a></td><td>Shipped (requires Opportunities; PDF + e-signature <strong>1.5.0</strong>; renewal reminders <strong>1.6.0</strong>)</td></tr><tr><td><a href="/user-guide/resellers-overview">Resellers</a> / <a href="/user-guide/reseller-payouts-overview">Reseller Payouts</a></td><td>Shipped (free Sales opt-ins; Payments → Resellers → Payouts chain)</td></tr></tbody></table><h3 id="deferred" tabindex="-1">Deferred <a class="header-anchor" href="#deferred" aria-label="Permalink to &quot;Deferred&quot;">​</a></h3><ul><li>Quotation multi-signer / third-party e-sign providers; multi-currency; approval workflows beyond status enums</li><li>Contract multi-signer / third-party e-sign providers; auto-renew boolean</li><li>Reseller cross-workspace identity; reseller portal; automated bank disbursement</li></ul><hr><h2 id="phase-3-—-billing-shipped" tabindex="-1">Phase 3 — Billing (shipped) <a class="header-anchor" href="#phase-3-—-billing-shipped" aria-label="Permalink to &quot;Phase 3 — Billing (shipped)&quot;">​</a></h2><p>Tenant customer billing — not a redesign of Central Marketplace billing.</p><table tabindex="0"><thead><tr><th>Capability</th><th>Status</th></tr></thead><tbody><tr><td><a href="/user-guide/invoices-overview">Invoices</a></td><td>Shipped</td></tr><tr><td><a href="/user-guide/estimates-overview">Estimates</a></td><td>Shipped (requires Invoices)</td></tr><tr><td><a href="/user-guide/credit-notes-overview">Credit Notes</a></td><td>Shipped <strong>1.2.0</strong> (requires Invoices; PDF + email; applied refund)</td></tr><tr><td><a href="/user-guide/payments-overview">Payments</a></td><td>Shipped (requires Invoices; receipt PDF + email shipped)</td></tr></tbody></table><h3 id="deferred-1" tabindex="-1">Deferred <a class="header-anchor" href="#deferred-1" aria-label="Permalink to &quot;Deferred&quot;">​</a></h3><ul><li>Credit Notes: standalone notes not tied to an invoice; multi-currency</li><li>Payments: partial refunds; payment-gateway capture</li><li>Invoices / Estimates: multi-currency conversion</li></ul><hr><h2 id="phase-4-—-purchasing-shipped" tabindex="-1">Phase 4 — Purchasing (shipped) <a class="header-anchor" href="#phase-4-—-purchasing-shipped" aria-label="Permalink to &quot;Phase 4 — Purchasing (shipped)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Status</th></tr></thead><tbody><tr><td><a href="/user-guide/vendors-overview">Vendors</a></td><td>Shipped</td></tr><tr><td><a href="/user-guide/purchase-orders-overview">Purchase Orders</a></td><td>Shipped (requires Vendors; PDF + email; per-line partial receive <strong>1.5.0</strong>)</td></tr><tr><td><a href="/user-guide/expenses-overview">Expenses</a></td><td>Shipped (soft Vendor / PO links; convert-from-PO)</td></tr></tbody></table><h3 id="deferred-2" tabindex="-1">Deferred <a class="header-anchor" href="#deferred-2" aria-label="Permalink to &quot;Deferred&quot;">​</a></h3><ul><li>Vendor portal / scorecards</li><li>Expense reimbursement workflows beyond <code>paid</code>; multi-line expenses</li></ul><hr><h2 id="phase-5-—-inventory-shipped" tabindex="-1">Phase 5 — Inventory (shipped) <a class="header-anchor" href="#phase-5-—-inventory-shipped" aria-label="Permalink to &quot;Phase 5 — Inventory (shipped)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Status</th></tr></thead><tbody><tr><td>Products &amp; categories</td><td>Shipped</td></tr><tr><td><a href="/user-guide/warehouses">Warehouses</a> &amp; <a href="/user-guide/inventory">Inventory</a></td><td>Shipped (Inventory requires Products)</td></tr><tr><td>PO receipt → stock-in (soft)</td><td>Shipped</td></tr></tbody></table><h3 id="deferred-3" tabindex="-1">Deferred <a class="header-anchor" href="#deferred-3" aria-label="Permalink to &quot;Deferred&quot;">​</a></h3><ul><li>Serial/lot control, valuation, COGS jobs</li></ul><hr><h2 id="phase-6-—-finance-shipped" tabindex="-1">Phase 6 — Finance (shipped) <a class="header-anchor" href="#phase-6-—-finance-shipped" aria-label="Permalink to &quot;Phase 6 — Finance (shipped)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Status</th></tr></thead><tbody><tr><td><a href="/user-guide/accounting-overview">Accounting</a> (CoA, journals, GL)</td><td>Shipped</td></tr><tr><td><a href="/user-guide/financial-reports">Financial Reports</a> (TB, P&amp;L, BS)</td><td>Shipped (requires Accounting)</td></tr><tr><td>Soft cash movements from Payments / Expenses / transfers</td><td>Shipped</td></tr></tbody></table><h3 id="deferred-4" tabindex="-1">Deferred <a class="header-anchor" href="#deferred-4" aria-label="Permalink to &quot;Deferred&quot;">​</a></h3><ul><li>Auto-post from POs / Inventory (AP/COGS)</li><li>Multi-currency accounting / FX; budgets</li></ul><hr><h2 id="phase-7-—-hr-shipped" tabindex="-1">Phase 7 — HR (shipped) <a class="header-anchor" href="#phase-7-—-hr-shipped" aria-label="Permalink to &quot;Phase 7 — HR (shipped)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Status</th></tr></thead><tbody><tr><td><a href="/user-guide/employees-overview">Employees</a></td><td>Shipped</td></tr><tr><td><a href="/user-guide/leave-management-overview">Leave Management</a></td><td>Shipped (requires Employees)</td></tr><tr><td><a href="/user-guide/attendance-overview">Attendance</a></td><td>Shipped (requires Employees; check-in/out timer)</td></tr><tr><td><a href="/user-guide/payroll-overview">Payroll</a></td><td>Shipped (requires Employees; optional Accounting post; own pay slips)</td></tr></tbody></table><h3 id="deferred-5" tabindex="-1">Deferred <a class="header-anchor" href="#deferred-5" aria-label="Permalink to &quot;Deferred&quot;">​</a></h3><ul><li>Org chart; employee self-service portal; leave accrual engines; biometric / geofencing; tax engines / bank file export</li></ul><hr><h2 id="phase-8-—-operations-shipped" tabindex="-1">Phase 8 — Operations (shipped) <a class="header-anchor" href="#phase-8-—-operations-shipped" aria-label="Permalink to &quot;Phase 8 — Operations (shipped)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Status</th></tr></thead><tbody><tr><td><a href="/user-guide/help-desk-overview">Help Desk</a></td><td>Shipped <strong>1.10.0</strong> (SLA + IMAP; @mentions; status Kanban; soft Communication Templates; shell File a complaint)</td></tr><tr><td><a href="/user-guide/projects-overview">Projects</a></td><td>Shipped (milestones <strong>1.4.0</strong>; soft Task <code>project_id</code> + dependencies <strong>tasks 1.5.0</strong>)</td></tr><tr><td><a href="/user-guide/knowledge-base-overview">Knowledge Base</a></td><td>Shipped (internal articles)</td></tr><tr><td><a href="/user-guide/assets-overview">Assets</a></td><td>Shipped</td></tr><tr><td><a href="/user-guide/documents-overview">Documents</a></td><td>Shipped (requires Storage)</td></tr><tr><td><a href="/user-guide/analytics-overview">Reports / Analytics</a></td><td>Shipped</td></tr><tr><td><a href="/user-guide/announcements-overview">Announcements</a></td><td>Shipped</td></tr><tr><td><a href="/user-guide/live-chat-overview">Live Chat</a></td><td>Shipped <strong>1.3.0</strong> (branding, offline hours, canned replies, Echo realtime, departments, media, Help Desk escalate, ban, Automation triggers)</td></tr></tbody></table><h3 id="help-desk-deferred" tabindex="-1">Help Desk deferred <a class="header-anchor" href="#help-desk-deferred" aria-label="Permalink to &quot;Help Desk deferred&quot;">​</a></h3><ul><li>Multi-channel intake beyond shared IMAP (chat, social)</li><li>Customer portal (external submit / track)</li></ul><h3 id="other-operations-deferred" tabindex="-1">Other Operations deferred <a class="header-anchor" href="#other-operations-deferred" aria-label="Permalink to &quot;Other Operations deferred&quot;">​</a></h3><ul><li>Projects: Gantt, workload heatmaps, Automation <code>create_project</code></li><li>Knowledge Base: public URLs, nested categories</li><li>Documents: nested folders, versioning, soft record links (on demand)</li><li>Assets: depreciation journals; Product/Inventory FKs; maintenance → Help Desk</li><li>Automation: Marketing campaigns / email campaigns (separate SKUs); branching; generate quote/invoice/order actions</li></ul><hr><h2 id="platform-add-ons-shipped" tabindex="-1">Platform add-ons (shipped) <a class="header-anchor" href="#platform-add-ons-shipped" aria-label="Permalink to &quot;Platform add-ons (shipped)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Status</th></tr></thead><tbody><tr><td><a href="/user-guide/branded">Branded</a> (white-label)</td><td>Shipped (billable)</td></tr><tr><td><a href="/user-guide/automation-overview">Automation</a></td><td>Shipped (billable)</td></tr><tr><td><a href="/user-guide/ai-assistant">AI Assistant</a></td><td>Shipped (billable; Lead Copilot + workspace search <strong>1.3.0</strong> + Help Desk triage <strong>1.4.0</strong> + Task triage <strong>1.5.0</strong> + Opportunity triage <strong>1.6.0</strong> + Invoice triage <strong>1.7.0</strong> + Expense triage <strong>1.8.0</strong> + Project triage <strong>1.9.0</strong> + PO triage <strong>1.10.0</strong> + Payment triage <strong>1.11.0</strong> + Lead assign/note <strong>1.12.0</strong> + Estimate triage <strong>1.13.0</strong> + Quotation triage <strong>1.14.0</strong> + Credit Note triage <strong>1.15.0</strong> + Leave triage <strong>1.16.0</strong> + confirmed writes)</td></tr><tr><td><a href="/user-guide/storage-overview">Storage</a></td><td>Shipped (free packs / quota)</td></tr><tr><td><a href="/developer-guide/tenant-api-webhooks">Tenant API &amp; Webhooks</a></td><td>Shipped (Settings → Developers; payment / Help Desk / credit-note events + endpoint edit)</td></tr><tr><td>Desktop wake push</td><td>Shipped (<strong>FCM only</strong>)</td></tr></tbody></table><hr><h2 id="elosync-mobile" tabindex="-1">EloSync Mobile <a class="header-anchor" href="#elosync-mobile" aria-label="Permalink to &quot;EloSync Mobile&quot;">​</a></h2><p>Native iOS/Android tenant app (Expo SDK 57). Broad module coverage shipped PR-by-PR (CRM, sales, billing, purchasing, HR, Ops, AI, Branded, Storage, etc.). Remaining gaps are module-specific (stats KPIs, trash, some PDF/settings panels remain web-only on mobile v1). See <a href="/user-guide/elosync-mobile">mobile user guide</a>.</p><hr><h2 id="near-term-depth" tabindex="-1">Near-term depth <a class="header-anchor" href="#near-term-depth" aria-label="Permalink to &quot;Near-term depth&quot;">​</a></h2><p>Depth program <strong>0 → 3c</strong> complete (2026-08-31): webhooks event catalog + Developers edit; Credit Notes applied refund (<strong>1.2.0</strong>); Help Desk <code>@mentions</code> <strong>1.5.0</strong>, Kanban <strong>1.6.0</strong>, Communication Template replies <strong>1.7.0</strong>.</p><p>AI workspace search shipped (<strong>ai 1.3.0</strong>): <code>search_workspace</code> fans out across entitled Wave A+B+C modules (CRM/sales/billing/purchasing/ops docs &amp; calendar records).</p><p>Help Desk AI triage shipped (<strong>ai 1.4.0</strong>): <code>get_help_desk_ticket</code> plus confirmed writes for status, assign, and notes (mirrors Help Desk API authz including close/reopen).</p><p>Task AI triage shipped (<strong>ai 1.5.0</strong>): <code>get_task</code> plus confirmed writes for status, assign, and notes (mirrors Task API authz including complete/reopen).</p><p>Opportunity AI triage shipped (<strong>ai 1.6.0</strong>): <code>get_opportunity</code> and <code>get_opportunity_stages</code> plus confirmed writes for stage, assign, and notes (mirrors Opportunity API authz; stage via <code>stage_id</code>).</p><p>Invoice AI triage shipped (<strong>ai 1.7.0</strong>): <code>get_invoice</code> plus confirmed writes for status, assign, and notes (mirrors Invoice HTTP <code>/status</code> authz including send/void gates; overdue list returns assignee id).</p><p>Expense AI triage shipped (<strong>ai 1.8.0</strong>): <code>get_expense</code> plus confirmed writes for status, assign, and notes (mirrors Expense HTTP <code>/status</code> authz including submit/approve/reject/pay/cancel gates; pending-approval list returns assignee id).</p><p>Project AI triage shipped (<strong>ai 1.9.0</strong>): confirmed writes for status, assign, and notes on existing project reads (mirrors Project HTTP <code>/status</code>; get returns assignee id).</p><p>Purchase Order AI triage shipped (<strong>ai 1.10.0</strong>): <code>get_purchase_order</code> plus confirmed writes for status, assign, and notes (mirrors PO HTTP <code>/status</code> authz including send/receive/cancel gates).</p><p>Payment AI triage shipped (<strong>ai 1.11.0</strong>): <code>get_payment</code> plus confirmed writes for status, assign, and notes (Posted→<code>post()</code>, Void→<code>void()</code>; Draft target rejected).</p><p>Lead assign + note shipped (<strong>ai 1.12.0</strong>): confirmed <code>assign_lead</code> / <code>add_lead_note</code> alongside existing Lead reads and status write.</p><p>Estimate AI triage shipped (<strong>ai 1.13.0</strong>): <code>get_estimate</code> plus confirmed writes for status, assign, and notes (mirrors Estimate HTTP <code>/status</code> authz including send/accept gates).</p><p>Quotation AI triage shipped (<strong>ai 1.14.0</strong>): <code>get_quotation</code> plus confirmed writes for status, assign, and notes (mirrors Quotation HTTP <code>/status</code> authz including send/accept gates; title only — no number field; assign uses <code>EligibleOpportunityAssignee</code>).</p><p>Credit Note AI triage shipped (<strong>ai 1.15.0</strong>): <code>get_credit_note</code> plus confirmed writes for status, assign, and notes (Issued→<code>issue()</code>, Applied→<code>apply()</code>, Void→<code>void()</code>, Refunded→<code>refund()</code>; Draft target rejected; assign uses <code>EligibleCreditNoteAssignee</code>).</p><p>Leave AI triage shipped (<strong>ai 1.16.0</strong>): <code>get_leave_request</code> + <code>get_pending_leave_requests</code> plus confirmed <code>approve_leave_request</code> / <code>reject_leave_request</code> (mirrors Leave HTTP approve/reject; no assign/notes; self-approve blocked for non-admin).</p><p>Contract PDF + e-signature shipped (<strong>contracts 1.5.0</strong>): branded PDF download, send-for-signature, customer accept links (reuse Quotation accept pattern), staff activate from sent, email with optional PDF + sign link.</p><p><strong>Phased depth Steps 1–4 + convert polish (2026-09-16):</strong> Projects milestones (<strong>projects 1.4.0</strong>) + task dependencies / <code>milestone_id</code> (<strong>tasks 1.5.0</strong>); contract renewal reminders via <code>crm:send-due-notifications</code> + <code>contract_renewal_notice_days</code> (<strong>contracts 1.6.0</strong>); PO per-line partial quantity receive (<strong>purchase-orders 1.5.0</strong>); Calendar Task/Lead overlays (<strong>calendar 1.1.0</strong>); Lead convert polish — <code>LeadConverted</code> / Automation <code>lead.converted</code>, company activity <code>ConvertedFromLead</code>, optional <code>company_id</code>/<code>company_name</code>, <code>conversion_meta</code> names (<strong>leads 1.5.0</strong>).</p><p>Still deferred: Gantt/heatmaps; Google/Outlook sync; team Calendar ACL; WhatsApp interactive; Customer Portal; multi-currency; PO/Vendor portals; contract auto-renew boolean.</p><p>Next when prioritized: WhatsApp interactive messages; demand-driven items below (broader AI tools continue lightly).</p><hr><h2 id="demand-driven-parked" tabindex="-1">Demand-driven / parked <a class="header-anchor" href="#demand-driven-parked" aria-label="Permalink to &quot;Demand-driven / parked&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Notes</th></tr></thead><tbody><tr><td>Customer Portal</td><td>External Help Desk submit/track — when beta demand is clear</td></tr><tr><td>Recruitment</td><td>HR expansion — on demand</td></tr><tr><td>Documents soft record links</td><td>On demand</td></tr><tr><td>Marketing campaigns / email campaigns</td><td>Separate SKUs; Automation deferred</td></tr><tr><td>Vendor Portal</td><td>Parked</td></tr><tr><td>Multi-currency / multi-branch</td><td>Parked</td></tr><tr><td>Report builder depth</td><td>Parked</td></tr><tr><td>Manufacturing, QA, POS, e-commerce</td><td>Out of active scope unless demanded</td></tr></tbody></table><hr><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/architecture/module-dependencies">Module dependencies</a></li><li><a href="/changelog/">Changelog</a></li><li><a href="/developer-guide/module-development-guide">Module development guide</a></li><li><a href="/getting-started/platform-freeze">Platform freeze</a></li></ul>',80)])])}const g=t(o,[["render",s]]);export{u as __pageData,g as default};
